async function visitLedger(stream, visitor) {
  const decoder = new TextDecoder("utf-8");
  const reader = stream.getReader();
  let accepted = 0;
  let rejected = 0;
  let line = 1;
  let reachedEOF = false;
  let parts = [];

  async function visitLine(text) {
    const physicalLine = line++;
    if (text.trim() === "") return true;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      rejected++;
      return true;
    }

    accepted++;
    return (await visitor({ line: physicalLine, value })) !== false;
  }

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) reachedEOF = true;

      const text = done
        ? decoder.decode()
        : decoder.decode(value, { stream: true });

      let start = 0;
      let end;

      while ((end = text.indexOf("\n", start)) !== -1) {
        let row = text.slice(start, end);
        if (parts.length > 0) {
          parts.push(row);
          row = parts.join("");
          parts = [];
        }

        if (!(await visitLine(row))) {
          return { accepted, rejected, stopped: true };
        }
        start = end + 1;
      }

      if (start < text.length) {
        parts.push(text.slice(start));
      }

      if (done) {
        if (parts.length > 0) {
          const row = parts.join("");
          parts = [];
          if (!(await visitLine(row))) {
            return { accepted, rejected, stopped: true };
          }
        }
        return { accepted, rejected, stopped: false };
      }
    }
  } finally {
    try {
      if (!reachedEOF) await reader.cancel();
    } finally {
      reader.releaseLock();
    }
  }
}
